// Normaliza lo que manda cada punto de aviso del flujo principal. Los
// niveles viejos ('aviso') pasan a 'info'. El mensaje ya viene escapado por el
// llamador (lleva HTML de Telegram: <b>, saltos de línea).
const NIVELES = ['info', 'atencion', 'critico'];
return $input.all().map((it) => {
  const e = it.json || {};
  const nivel = NIVELES.includes(e.nivel) ? e.nivel : 'info';
  return { json: {
    tipo: String(e.tipo || 'aviso').slice(0, 60),
    nivel,
    mensaje: String(e.mensaje || '').slice(0, 4000),
    lead_id: String(e.lead_id || ''),
    factura_id: String(e.factura_id || ''),
    espacio_id: /^[0-9a-f-]{36}$/i.test(String(e.espacio_id || '')) ? String(e.espacio_id) : '',
  } };
});

// A qué chats de Telegram va cada aviso:
//  - al del desarrollador, si lo vinculó desde el panel;
//  - al de la plataforma, si el aviso es crítico o no es de ningún espacio.
const leerEnv = (clave) => {
  try { return (typeof $env !== 'undefined' && $env) ? ($env[clave] || '') : ''; } catch (e) { return ''; }
};
const plataforma = leerEnv('TELEGRAM_CHAT_ID_CRITICO') || leerEnv('TELEGRAM_CHAT_ID');
const out = [];
for (const it of $input.all()) {
  const a = it.json;
  const chats = new Set();
  if (a.telegram_chat_id) chats.add(String(a.telegram_chat_id));
  if ((a.nivel === 'critico' || !a.espacio_id) && plataforma) chats.add(plataforma);
  for (const chatId of chats) out.push({ json: { chatId, mensaje: a.mensaje } });
}
return out;

// Por correo van sólo los avisos que le piden algo al desarrollador
// ('atencion' y 'critico'); los informativos quedan en el panel y en Telegram,
// para no llenarle la casilla. El mensaje ya viene escapado: se pasan los
// saltos de línea a <br>.
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const leerEnv = (clave, porDefecto) => {
  try { const v = (typeof $env !== 'undefined' && $env) ? $env[clave] : undefined; return v ? String(v) : porDefecto; } catch (e) { return porDefecto; }
};
const plataforma = leerEnv('PLATAFORMA_NOMBRE', 'FormularioLeads');
const panel = leerEnv('FRONTEND_URL', 'http://localhost:3000').replace(/\/+$/, '') + '/dashboard';
const TITULOS = {
  pago_recibido: 'Entró un pago', lead_acepto: 'Aceptaron tu propuesta', pago_urgente: 'Una factura necesita atención',
  lead_rechazado: 'Rechazaron una propuesta', pedido_cambios: 'Te pidieron cambios', propuesta_por_enviar: 'Tenés una propuesta por enviar',
  propuestas_pendientes: 'Hay una propuesta esperando', facturas_vencidas: 'Hay facturas vencidas', pago_no_aplicado: 'Un pago no se pudo aplicar',
};
const out = [];
for (const it of $input.all()) {
  const a = it.json;
  if (!a.espacio_email || (a.nivel !== 'atencion' && a.nivel !== 'critico')) continue;
  const titulo = TITULOS[a.tipo] || 'Novedades en tu panel';
  const html = "<div style='font-family:Arial,Helvetica,sans-serif;color:#27272a;max-width:560px'>" +
    "<p style='font-size:15px;line-height:1.6'>" + String(a.mensaje).replace(/\n/g, '<br>') + '</p>' +
    "<p style='margin:24px 0'><a href='" + esc(panel) + "' style='background:#111827;color:#fff;padding:12px 22px;border-radius:6px;text-decoration:none;font-size:14px'>Abrir el panel</a></p>" +
    "<p style='font-size:12px;color:#71717a'>Te llega porque es un aviso de " + esc(a.espacio_nombre || 'tu espacio') + ' en ' + esc(plataforma) + '.</p></div>';
  out.push({ json: { para: a.espacio_email, asunto: titulo + ' — ' + (a.espacio_nombre || plataforma), html } });
}
return out;
